"use strict";(self.webpackChunkenterprise_ai_agents_applied_ml_book=self.webpackChunkenterprise_ai_agents_applied_ml_book||[]).push([[7846],{8022(e,t,n){n.r(t),n.d(t,{assets:()=>c,contentTitle:()=>d,default:()=>g,frontMatter:()=>l,metadata:()=>a,toc:()=>h});const a=JSON.parse('{"id":"part5-deep-learning-and-llms/autoregressive-linear-model","title":"Forecasting (Code): Coding an Autoregressive Linear Model in PyTorch","description":"Goal: implement an autoregressive (AR) linear model for time-series prediction, then evaluate it in the right way for a multi-step forecast.","source":"@site/docs/part5-deep-learning-and-llms/09-autoregressive-linear-model.mdx","sourceDirName":"part5-deep-learning-and-llms","slug":"/part5-deep-learning-and-llms/09-autoregressive-linear-model","permalink":"/tutorials/part5-deep-learning-and-llms/09-autoregressive-linear-model","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1785375762000,"sidebarPosition":9,"frontMatter":{"title":"Forecasting (Code): Coding an Autoregressive Linear Model in PyTorch","slug":"/part5-deep-learning-and-llms/09-autoregressive-linear-model","description":"Goal: implement an autoregressive (AR) linear model for time-series prediction, then evaluate it in the right way for a multi-step forecast.","sidebar_label":"9. Autoregressive linear model","pagination_label":"9. Autoregressive linear model","hide_title":true,"hide_table_of_contents":true},"sidebar":"bookSidebar","previous":{"title":"8. Forecasting and sequence data","permalink":"/tutorials/part5-deep-learning-and-llms/08-forecasting-sequence-data"},"next":{"title":"10. Recurrent neural networks","permalink":"/tutorials/part5-deep-learning-and-llms/10-recurrent-neural-networks"}}');var i=n(4848),r=n(8453),s=n(8172);const o=JSON.parse('{"sourcePath":"part5-deep-learning-and-llms/09-autoregressive-linear-model.html","route":"/part5-deep-learning-and-llms/09-autoregressive-linear-model","kind":"chapter","partId":"part5","partLabel":"Part V - Deep Learning & Large Language Models","accent":"coral","heading":"Forecasting (Code): Autoregressive Linear Model in PyTorch","title":"Forecasting (Code): Coding an Autoregressive Linear Model in PyTorch","description":"Goal: implement an autoregressive (AR) linear model for time-series prediction, then evaluate it in the right way for a multi-step forecast.","readingMinutes":8,"bodyClass":"","normalizeMath":false,"toc":[{"id":"1-what-this-chapter-is-building","label":"1) What this chapter is building"},{"id":"2-create-a-controlled-time-series","label":"2) Create a controlled time series"},{"id":"3-build-the-dataset-by-windowing","label":"3) Build the dataset by windowing"},{"id":"4-chronological-split-split-by-time-not-randomly","label":"4) Chronological split: split by time, not randomly"},{"id":"5-define-the-ar-model-in-pytorch","label":"5) Define the AR model in PyTorch"},{"id":"6-train-with-full-batch-gradient-descent","label":"6) Train with full-batch gradient descent"},{"id":"7-one-step-validation-vs-real-multi-step-forecasting","label":"7) One-step validation vs real multi-step forecasting"},{"id":"8-compare-metrics","label":"8) Compare metrics"},{"id":"9-why-can-a-linear-ar-model-predict-a-sine-wave-so-well","label":"9) Why can a linear AR model predict a sine wave so well?"},{"id":"10-extending-the-baseline","label":"10) Extending the baseline"},{"id":"11-common-gotchas-checklist","label":"11) Common gotchas checklist"}],"html":"<main class=\\"wrap\\">\\n  <header class=\\"card\\">\\n    \\n    <p class=\\"muted\\">\\n      Goal: implement an <strong>autoregressive (AR)</strong> linear model for time-series prediction, then evaluate it\\n      in the right way for a multi-step forecast.\\n    </p>\\n  </header>\\n\\n  <section>\\n    <h2 id=\\"1-what-this-chapter-is-building\\">1) What this chapter is building</h2>\\n    <div class=\\"card\\">\\n      <p>\\n        Chapter 8 introduced the concept: turn a time series into supervised windows, train a simple baseline, and be careful\\n        not to leak future values. Here we implement that baseline in PyTorch.\\n      </p>\\n      <p>\\n        The model is intentionally simple:\\n      </p>\\n      <div class=\\"eq\\">\\n        \\\\[\\n          \\\\hat{x}_{t} = b + w_1x_{t-1} + w_2x_{t-2} + \\\\dots + w_Tx_{t-T}\\n        \\\\]\\n      </div>\\n      <p>\\n        That is just a linear layer from a lookback window of length \\\\(T\\\\) to one scalar prediction. The point is not that\\n        this model is always powerful. The point is that it is the cleanest baseline for learning the mechanics of forecasting:\\n        windowing, chronological splitting, training, and recursive evaluation.\\n      </p>\\n    </div>\\n\\n    <figure>\\n      <svg class=\\"viz\\" viewBox=\\"0 0 980 285\\" role=\\"img\\" aria-label=\\"Autoregressive linear model maps a lookback window to next value\\">\\n        <defs>\\n          <marker id=\\"ar-code-arrow\\" markerWidth=\\"10\\" markerHeight=\\"10\\" refX=\\"8\\" refY=\\"3\\" orient=\\"auto\\">\\n            <path d=\\"M0,0 L8,3 L0,6 Z\\" fill=\\"#0969da\\"></path>\\n          </marker>\\n        </defs>\\n        <text x=\\"30\\" y=\\"34\\" class=\\"title\\">Autoregressive linear model</text>\\n        <text x=\\"30\\" y=\\"60\\" class=\\"muted\\">The previous T values become the feature vector for one next-step prediction.</text>\\n\\n        <g transform=\\"translate(70,118)\\">\\n          <rect x=\\"0\\" y=\\"0\\" width=\\"72\\" height=\\"52\\" rx=\\"10\\" fill=\\"#eaf3ff\\" stroke=\\"#0969da\\"></rect>\\n          <rect x=\\"92\\" y=\\"0\\" width=\\"72\\" height=\\"52\\" rx=\\"10\\" fill=\\"#eaf3ff\\" stroke=\\"#0969da\\"></rect>\\n          <rect x=\\"184\\" y=\\"0\\" width=\\"72\\" height=\\"52\\" rx=\\"10\\" fill=\\"#eaf3ff\\" stroke=\\"#0969da\\"></rect>\\n          <rect x=\\"276\\" y=\\"0\\" width=\\"72\\" height=\\"52\\" rx=\\"10\\" fill=\\"#eaf3ff\\" stroke=\\"#0969da\\"></rect>\\n          <text x=\\"36\\" y=\\"32\\" class=\\"label\\" text-anchor=\\"middle\\">x[t-3]</text>\\n          <text x=\\"128\\" y=\\"32\\" class=\\"label\\" text-anchor=\\"middle\\">x[t-2]</text>\\n          <text x=\\"220\\" y=\\"32\\" class=\\"label\\" text-anchor=\\"middle\\">x[t-1]</text>\\n          <text x=\\"312\\" y=\\"32\\" class=\\"label\\" text-anchor=\\"middle\\">x[t]</text>\\n          <text x=\\"174\\" y=\\"88\\" class=\\"muted\\" text-anchor=\\"middle\\">input vector shape: (T,)</text>\\n        </g>\\n\\n        <rect x=\\"505\\" y=\\"112\\" width=\\"150\\" height=\\"64\\" rx=\\"14\\" fill=\\"#f5f0ff\\" stroke=\\"#8250df\\"></rect>\\n        <text x=\\"580\\" y=\\"138\\" class=\\"label\\" text-anchor=\\"middle\\">nn.Linear</text>\\n        <text x=\\"580\\" y=\\"160\\" class=\\"muted\\" text-anchor=\\"middle\\">T -&gt; 1</text>\\n\\n        <rect x=\\"760\\" y=\\"112\\" width=\\"116\\" height=\\"64\\" rx=\\"14\\" fill=\\"#f3f8f1\\" stroke=\\"#1a7f37\\"></rect>\\n        <text x=\\"818\\" y=\\"138\\" class=\\"label\\" text-anchor=\\"middle\\">xhat[t+1]</text>\\n        <text x=\\"818\\" y=\\"160\\" class=\\"muted\\" text-anchor=\\"middle\\">next value</text>\\n\\n        <path fill=\\"none\\" d=\\"M420 144 L505 144 M655 144 L760 144\\" stroke=\\"#0969da\\" stroke-width=\\"2.5\\" marker-end=\\"url(#ar-code-arrow)\\"></path>\\n      </svg>\\n      <figcaption>\\n        This is a regular supervised model. What makes it time-series forecasting is how the supervised examples are constructed and evaluated.\\n      </figcaption>\\n    </figure>\\n  </section>\\n\\n  <section>\\n    <h2 id=\\"2-create-a-controlled-time-series\\">2) Create a controlled time series</h2>\\n    <div class=\\"card\\">\\n      <p>\\n        A sine wave is useful because it is periodic, smooth, and easy to debug. We can add noise later to make the problem\\n        more realistic. Starting clean is a good engineering habit: if the simple case fails, the bug is probably in the data\\n        shaping or evaluation logic.\\n      </p>\\n      <img src=\\"/tutorials/images/external/Sine_wave-abf800537c-fallback.svg\\" alt=\\"Sine wave plot\\" style=\\"max-width:720px; width:100%; border:1px solid var(--border); border-radius:12px;\\">\\n    </div>\\n\\n<pre><code class=\\"language-python\\"># --- Imports ---\\nimport numpy as np\\nimport torch\\nimport torch.nn as nn\\nimport matplotlib.pyplot as plt\\n\\nnp.random.seed(0)\\ntorch.manual_seed(0)\\n\\n# --- 1) Create a synthetic time series ---\\nN = 1000\\nomega = 0.1\\nt = np.arange(N)\\nseries = np.sin(omega * t).astype(np.float32)\\n\\n# Optional: make the task more realistic after the clean version works.\\n# noise_std = 0.2\\n# series = (series + noise_std * np.random.randn(N)).astype(np.float32)\\n\\nplt.figure(figsize=(10, 3))\\nplt.plot(series)\\nplt.title(\\"Synthetic time series\\")\\nplt.xlabel(\\"time index\\")\\nplt.ylabel(\\"x[t]\\")\\nplt.show()</code></pre>\\n  </section>\\n\\n  <section>\\n    <h2 id=\\"3-build-the-dataset-by-windowing\\">3) Build the dataset by windowing</h2>\\n    <div class=\\"card\\">\\n      <p>\\n        Windowing is where most forecasting bugs begin. For each target time, the model should only see values before that\\n        target. If \\\\(T=10\\\\), then one example looks like this:\\n      </p>\\n      <div class=\\"eq\\">\\n        <div><strong>Input:</strong> \\\\([x_t, x_{t+1}, \\\\dots, x_{t+T-1}]\\\\)</div>\\n        <div><strong>Target:</strong> \\\\(x_{t+T}\\\\)</div>\\n      </div>\\n      <p>\\n        The input has shape \\\\((T,)\\\\). The target is one scalar. Once we stack all windows, \\\\(X\\\\) has shape\\n        \\\\((\\\\text{num_windows}, T)\\\\) and \\\\(y\\\\) has shape \\\\((\\\\text{num_windows}, 1)\\\\).\\n      </p>\\n    </div>\\n\\n<pre><code class=\\"language-python\\">def make_windows(series: np.ndarray, lookback: int):\\n    \\"\\"\\"\\n    X[i] = series[i : i+lookback]\\n    y[i] = series[i+lookback]\\n\\n    Also returns target_times so we can split by the target\'s time index.\\n    \\"\\"\\"\\n    series = np.asarray(series, dtype=np.float32)\\n    if len(series) &lt;= lookback:\\n        raise ValueError(\\"series is too short for the chosen lookback\\")\\n\\n    X, y, target_times = [], [], []\\n    for start in range(len(series) - lookback):\\n        end = start + lookback\\n        X.append(series[start:end])\\n        y.append(series[end])\\n        target_times.append(end)\\n\\n    X = np.asarray(X, dtype=np.float32)\\n    y = np.asarray(y, dtype=np.float32).reshape(-1, 1)\\n    target_times = np.asarray(target_times)\\n    return X, y, target_times\\n\\nT = 10\\nX, y, target_times = make_windows(series, lookback=T)\\n\\nprint(\\"X shape:\\", X.shape)  # (N-T, T)\\nprint(\\"y shape:\\", y.shape)  # (N-T, 1)\\nprint(\\"First window:\\", X[0])\\nprint(\\"First target:\\", y[0, 0])</code></pre>\\n\\n    <div class=\\"card\\">\\n      <h3 id=\\"a-tiny-off-by-one-sanity-check\\">A tiny off-by-one sanity check</h3>\\n      <p>\\n        If `series = [0, 1, 2, 3, 4]` and `T = 2`, the windows should be:\\n      </p>\\n      <table>\\n        <thead><tr><th>Input window</th><th>Target</th></tr></thead>\\n        <tbody>\\n          <tr><td>[0, 1]</td><td>2</td></tr>\\n          <tr><td>[1, 2]</td><td>3</td></tr>\\n          <tr><td>[2, 3]</td><td>4</td></tr>\\n        </tbody>\\n      </table>\\n      <p class=\\"mini\\">\\n        If your code produces a different table, fix the indexing before training anything.\\n      </p>\\n    </div>\\n  </section>\\n\\n  <section>\\n    <h2 id=\\"4-chronological-split-split-by-time-not-randomly\\">4) Chronological split: split by time, not randomly</h2>\\n    <div class=\\"card warn\\">\\n      <p>\\n        For time series, do <strong>not</strong> randomly shuffle examples before deciding train and validation. A forecast\\n        should train on the past and validate on the future.\\n      </p>\\n    </div>\\n\\n    <div class=\\"card\\">\\n      <p>\\n        A subtle but important point: split according to the <strong>target time</strong>. The first validation example may use\\n        a lookback window that contains the last observed training values. That is not leakage; at the validation forecast origin,\\n        those historical values are known. Leakage begins when you use true values after the forecast origin while rolling forward.\\n      </p>\\n    </div>\\n\\n<pre><code class=\\"language-python\\"># Target times before this point are training targets.\\nsplit_time = int(0.6 * N)\\n\\ntrain_mask = target_times &lt; split_time\\nval_mask = target_times &gt;= split_time\\n\\nX_train, y_train = X[train_mask], y[train_mask]\\nX_val, y_val = X[val_mask], y[val_mask]\\ntarget_times_val = target_times[val_mask]\\n\\nprint(\\"train:\\", X_train.shape, y_train.shape)\\nprint(\\"val:\\", X_val.shape, y_val.shape)\\n\\n# Convert to torch tensors.\\nX_train_t = torch.tensor(X_train, dtype=torch.float32)\\ny_train_t = torch.tensor(y_train, dtype=torch.float32)\\nX_val_t = torch.tensor(X_val, dtype=torch.float32)\\ny_val_t = torch.tensor(y_val, dtype=torch.float32)</code></pre>\\n\\n    <div class=\\"card\\">\\n      <h3 id=\\"where-scaling-belongs\\">Where scaling belongs</h3>\\n      <p>\\n        If you standardize the series, fit the mean and standard deviation on the training period only, then apply those same\\n        statistics to validation/test. Fitting a scaler on the full series leaks future distribution information.\\n      </p>\\n<pre><code class=\\"language-python\\"># Optional scaling pattern. Fit only on observed training history.\\ntrain_values_for_scaler = series[:split_time]\\nmean = train_values_for_scaler.mean()\\nstd = train_values_for_scaler.std() + 1e-8\\n\\nseries_scaled = (series - mean) / std\\n# Then rebuild windows from series_scaled using the same function.</code></pre>\\n    </div>\\n  </section>\\n\\n  <section>\\n    <h2 id=\\"5-define-the-ar-model-in-pytorch\\">5) Define the AR model in PyTorch</h2>\\n    <div class=\\"card\\">\\n      <p>\\n        The AR(\\\\(T\\\\)) linear model is one layer:\\n      </p>\\n      <div class=\\"eq\\">\\n        \\\\[\\n          \\\\hat{x}_{t+T} = b + \\\\sum_{i=0}^{T-1} w_i x_{t+i}\\n        \\\\]\\n      </div>\\n      <p>\\n        In PyTorch, `nn.Linear(T, 1)` stores the \\\\(T\\\\) lag weights plus one bias. It receives a batch of windows with shape\\n        \\\\((B,T)\\\\) and returns \\\\((B,1)\\\\).\\n      </p>\\n    </div>\\n\\n<pre><code class=\\"language-python\\">model = nn.Linear(T, 1)\\n\\nloss_fn = nn.MSELoss()\\noptimizer = torch.optim.Adam(model.parameters(), lr=0.05)\\n\\nprint(model)\\nprint(\\"weight shape:\\", model.weight.shape)  # (1, T)\\nprint(\\"bias shape:\\", model.bias.shape)      # (1,)</code></pre>\\n  </section>\\n\\n  <section>\\n    <h2 id=\\"6-train-with-full-batch-gradient-descent\\">6) Train with full-batch gradient descent</h2>\\n    <div class=\\"card\\">\\n      <p>\\n        Because this dataset is small, we can use all training windows each step. For larger datasets, you would use mini-batches\\n        with a `DataLoader`. The forecasting logic below is unchanged.\\n      </p>\\n    </div>\\n\\n<pre><code class=\\"language-python\\">def train_full_gd(model, Xtr, ytr, epochs=300):\\n    losses = []\\n    for epoch in range(epochs):\\n        model.train()\\n\\n        pred = model(Xtr)          # (num_train_windows, 1)\\n        loss = loss_fn(pred, ytr)\\n\\n        optimizer.zero_grad()\\n        loss.backward()\\n        optimizer.step()\\n\\n        losses.append(loss.item())\\n    return losses\\n\\nlosses = train_full_gd(model, X_train_t, y_train_t, epochs=300)\\n\\nplt.figure(figsize=(8, 3))\\nplt.plot(losses)\\nplt.title(\\"Training loss (MSE)\\")\\nplt.xlabel(\\"epoch\\")\\nplt.ylabel(\\"loss\\")\\nplt.show()</code></pre>\\n\\n    <div class=\\"card\\">\\n      <h3 id=\\"check-the-learned-lag-weights\\">Check the learned lag weights</h3>\\n      <p>\\n        A linear AR model is interpretable. The learned weights show which lags are useful. For a clean sine wave, only a\\n        small number of lags are theoretically necessary, although a larger lookback can still learn a good recurrence.\\n      </p>\\n<pre><code class=\\"language-python\\">with torch.no_grad():\\n    weights = model.weight.detach().cpu().numpy().ravel()\\n    bias = float(model.bias.detach().cpu())\\n\\nprint(\\"bias:\\", bias)\\nprint(\\"lag weights:\\", np.round(weights, 3))</code></pre>\\n    </div>\\n  </section>\\n\\n  <section>\\n    <h2 id=\\"7-one-step-validation-vs-real-multi-step-forecasting\\">7) One-step validation vs real multi-step forecasting</h2>\\n\\n    <div class=\\"card warn\\">\\n      <h3 id=\\"the-wrong-answer-to-the-wrong-question\\">The wrong answer to the wrong question</h3>\\n      <p>\\n        If you run `model(X_val_t)`, every validation prediction receives a window containing true historical values from\\n        the validation period. That is a valid <strong>one-step-ahead</strong> evaluation, but it is not a valid 50-step\\n        forecast from a single origin.\\n      </p>\\n      <p>\\n        It answers: \u201cHow good is the model if the latest real observation is always available before each prediction?\u201d\\n        It does not answer: \u201cWhat happens if I stand at the split point and forecast the next 50 unknown values?\u201d\\n      </p>\\n    </div>\\n\\n<pre><code class=\\"language-python\\"># One-step-ahead validation. Useful, but not a multi-step forecast.\\nmodel.eval()\\nwith torch.no_grad():\\n    one_step_preds = model(X_val_t).squeeze(1).cpu().numpy()\\n\\nplt.figure(figsize=(10, 3))\\nplt.plot(y_val.squeeze(), label=\\"target\\")\\nplt.plot(one_step_preds, label=\\"one-step predictions\\")\\nplt.title(\\"One-step validation: true windows are supplied each step\\")\\nplt.legend()\\nplt.show()</code></pre>\\n\\n    <div class=\\"card ok\\">\\n      <h3 id=\\"the-correct-recursive-forecast\\">The correct recursive forecast</h3>\\n      <p>\\n        For a multi-step forecast, start from one known lookback window. Predict the next value, append that prediction to\\n        the window, drop the oldest value, and repeat.\\n      </p>\\n    </div>\\n\\n<pre><code class=\\"language-python\\">def recursive_forecast_torch(model, start_window, horizon):\\n    \\"\\"\\"\\n    start_window: shape (T,), the last known values at the forecast origin.\\n    horizon: number of future steps to predict.\\n    \\"\\"\\"\\n    model.eval()\\n    window = torch.tensor(start_window, dtype=torch.float32).clone()\\n    preds = []\\n\\n    with torch.no_grad():\\n        for _ in range(horizon):\\n            y_hat = model(window.view(1, -1))       # (1, 1)\\n            y_scalar = y_hat.view(())               # scalar tensor\\n            preds.append(float(y_scalar))\\n\\n            # Drop oldest value and append the model\'s prediction.\\n            window = torch.cat([window[1:], y_scalar.view(1)])\\n\\n    return np.asarray(preds, dtype=np.float32)\\n\\nhorizon = len(y_val)\\nstart_window = X_val[0]  # known context at the first validation target\\nrecursive_preds = recursive_forecast_torch(model, start_window, horizon=horizon)\\n\\nplt.figure(figsize=(10, 3))\\nplt.plot(y_val.squeeze(), label=\\"target\\")\\nplt.plot(recursive_preds, label=\\"recursive forecast\\")\\nplt.title(\\"Recursive validation: predictions feed future predictions\\")\\nplt.legend()\\nplt.show()</code></pre>\\n\\n    <figure>\\n      <svg class=\\"viz\\" viewBox=\\"0 0 980 310\\" role=\\"img\\" aria-label=\\"Teacher-forced one-step validation compared with recursive forecasting\\">\\n        <defs>\\n          <marker id=\\"wrong-right-arrow\\" markerWidth=\\"10\\" markerHeight=\\"10\\" refX=\\"8\\" refY=\\"3\\" orient=\\"auto\\">\\n            <path d=\\"M0,0 L8,3 L0,6 Z\\" fill=\\"#0969da\\"></path>\\n          </marker>\\n        </defs>\\n        <text x=\\"30\\" y=\\"34\\" class=\\"title\\">Two validation modes answer different questions</text>\\n        <text x=\\"30\\" y=\\"60\\" class=\\"muted\\">One-step validation is not bad; it is just not the same as a long-horizon forecast.</text>\\n\\n        <g transform=\\"translate(70,112)\\">\\n          <text x=\\"172\\" y=\\"-18\\" class=\\"label\\" text-anchor=\\"middle\\">one-step / true-window mode</text>\\n          <rect x=\\"0\\" y=\\"22\\" width=\\"96\\" height=\\"48\\" rx=\\"10\\" fill=\\"#eaf3ff\\" stroke=\\"#0969da\\"></rect>\\n          <rect x=\\"118\\" y=\\"22\\" width=\\"96\\" height=\\"48\\" rx=\\"10\\" fill=\\"#eaf3ff\\" stroke=\\"#0969da\\"></rect>\\n          <rect x=\\"236\\" y=\\"22\\" width=\\"96\\" height=\\"48\\" rx=\\"10\\" fill=\\"#eaf3ff\\" stroke=\\"#0969da\\"></rect>\\n          <text x=\\"48\\" y=\\"52\\" class=\\"label\\" text-anchor=\\"middle\\">true x</text>\\n          <text x=\\"166\\" y=\\"52\\" class=\\"label\\" text-anchor=\\"middle\\">true x</text>\\n          <text x=\\"284\\" y=\\"52\\" class=\\"label\\" text-anchor=\\"middle\\">true x</text>\\n          <path fill=\\"none\\" d=\\"M48 70 L48 116 M166 70 L166 116 M284 70 L284 116\\" stroke=\\"#0969da\\" stroke-width=\\"2.2\\" marker-end=\\"url(#wrong-right-arrow)\\"></path>\\n          <text x=\\"172\\" y=\\"146\\" class=\\"muted\\" text-anchor=\\"middle\\">measures one-step prediction quality</text>\\n        </g>\\n\\n        <g transform=\\"translate(570,112)\\">\\n          <text x=\\"172\\" y=\\"-18\\" class=\\"label\\" text-anchor=\\"middle\\">recursive forecast mode</text>\\n          <rect x=\\"0\\" y=\\"22\\" width=\\"96\\" height=\\"48\\" rx=\\"10\\" fill=\\"#eaf3ff\\" stroke=\\"#0969da\\"></rect>\\n          <rect x=\\"118\\" y=\\"22\\" width=\\"96\\" height=\\"48\\" rx=\\"10\\" fill=\\"#f3f8f1\\" stroke=\\"#1a7f37\\"></rect>\\n          <rect x=\\"236\\" y=\\"22\\" width=\\"96\\" height=\\"48\\" rx=\\"10\\" fill=\\"#f3f8f1\\" stroke=\\"#1a7f37\\"></rect>\\n          <text x=\\"48\\" y=\\"52\\" class=\\"label\\" text-anchor=\\"middle\\">true x</text>\\n          <text x=\\"166\\" y=\\"52\\" class=\\"label\\" text-anchor=\\"middle\\">xhat</text>\\n          <text x=\\"284\\" y=\\"52\\" class=\\"label\\" text-anchor=\\"middle\\">xhat</text>\\n          <path fill=\\"none\\" d=\\"M96 46 L118 46 M214 46 L236 46\\" stroke=\\"#1a7f37\\" stroke-width=\\"2.2\\" marker-end=\\"url(#wrong-right-arrow)\\"></path>\\n          <text x=\\"172\\" y=\\"146\\" class=\\"muted\\" text-anchor=\\"middle\\">measures long-horizon drift and compounding error</text>\\n        </g>\\n      </svg>\\n      <figcaption>\\n        The \u201cwrong\u201d plot can look excellent because every step gets true context. The recursive plot is the honest simulation of standing at one origin and rolling forward.\\n      </figcaption>\\n    </figure>\\n  </section>\\n\\n  <section>\\n    <h2 id=\\"8-compare-metrics\\">8) Compare metrics</h2>\\n    <div class=\\"card\\">\\n      <p>\\n        Use the same target array for both predictions. The one-step result is usually better because it receives true\\n        validation inputs at every step. The recursive forecast is the harder and more realistic multi-step test.\\n      </p>\\n    </div>\\n\\n<pre><code class=\\"language-python\\">def mae(y_true, y_pred):\\n    return np.mean(np.abs(y_true - y_pred))\\n\\ndef rmse(y_true, y_pred):\\n    return np.sqrt(np.mean((y_true - y_pred) ** 2))\\n\\ny_true = y_val.squeeze()\\n\\nprint(\\"One-step MAE:\\", mae(y_true, one_step_preds))\\nprint(\\"One-step RMSE:\\", rmse(y_true, one_step_preds))\\nprint(\\"Recursive MAE:\\", mae(y_true, recursive_preds))\\nprint(\\"Recursive RMSE:\\", rmse(y_true, recursive_preds))</code></pre>\\n\\n    <div class=\\"card\\">\\n      <h3 id=\\"what-you-should-observe\\">What you should observe</h3>\\n      <ul>\\n        <li><strong>No-noise sine wave:</strong> both methods can look nearly perfect because the signal follows a clean recurrence.</li>\\n        <li><strong>Noisy sine wave:</strong> one-step validation often still looks good, while recursive forecasting drifts as errors compound.</li>\\n        <li><strong>Real business series:</strong> regime changes, promotions, holidays, missing data, and exogenous variables often matter more than model complexity.</li>\\n      </ul>\\n    </div>\\n  </section>\\n\\n  <section>\\n    <h2 id=\\"9-why-can-a-linear-ar-model-predict-a-sine-wave-so-well\\">9) Why can a linear AR model predict a sine wave so well?</h2>\\n    <div class=\\"card\\">\\n      <p>\\n        A sine wave has an exact <strong>2-step linear recurrence</strong>. If \\\\(x_t = \\\\sin(\\\\omega t)\\\\), then:\\n      </p>\\n\\n      <div class=\\"eq\\">\\n        \\\\[\\n          x_{t+1} = 2\\\\cos(\\\\omega)\\\\,x_t - x_{t-1}\\n        \\\\]\\n      </div>\\n\\n      <p>\\n        This means an AR(2) model can represent a clean sine wave perfectly. Using \\\\(T=10\\\\) gives the model more lags than it\\n        strictly needs, but the linear layer can learn weights that implement the recurrence. Noise breaks the exact recurrence,\\n        which is why recursive forecasting becomes imperfect.\\n      </p>\\n    </div>\\n\\n    <div class=\\"card\\">\\n      <h3 id=\\"sketch-of-the-derivation\\">Sketch of the derivation</h3>\\n      <p>\\n        Use the identity:\\n        \\\\[\\n          \\\\sin(a+b) + \\\\sin(a-b) = 2\\\\sin(a)\\\\cos(b)\\n        \\\\]\\n        Let \\\\(a = \\\\omega t\\\\) and \\\\(b = \\\\omega\\\\). Then:\\n        \\\\[\\n          \\\\sin(\\\\omega(t+1)) + \\\\sin(\\\\omega(t-1)) = 2\\\\sin(\\\\omega t)\\\\cos(\\\\omega)\\n        \\\\]\\n        Rearranging gives:\\n        \\\\[\\n          \\\\sin(\\\\omega(t+1)) = 2\\\\cos(\\\\omega)\\\\sin(\\\\omega t) - \\\\sin(\\\\omega(t-1))\\n        \\\\]\\n      </p>\\n    </div>\\n  </section>\\n\\n  <section>\\n    <h2 id=\\"10-extending-the-baseline\\">10) Extending the baseline</h2>\\n    <div class=\\"card\\">\\n      <p>\\n        The same shape logic extends naturally:\\n      </p>\\n      <ul>\\n        <li><strong>More input features:</strong> use \\\\(D&gt;1\\\\), such as demand plus price, holiday flag, and weather.</li>\\n        <li><strong>Multi-output forecasting:</strong> change the output layer from `nn.Linear(T, 1)` to `nn.Linear(T, H)`.</li>\\n        <li><strong>Nonlinear baseline:</strong> replace the single linear layer with a small MLP.</li>\\n        <li><strong>RNN baseline:</strong> keep the sequence axis instead of flattening the lookback into one vector.</li>\\n      </ul>\\n    </div>\\n\\n<pre><code class=\\"language-python\\"># Multi-output direct forecast sketch:\\n# input window -&gt; next H values at once.\\nH = 24\\nmulti_output_model = nn.Linear(T, H)\\n\\n# For this model, y would need shape (num_windows, H), not (num_windows, 1).</code></pre>\\n  </section>\\n\\n  <section>\\n    <h2 id=\\"11-common-gotchas-checklist\\">11) Common gotchas checklist</h2>\\n    <div class=\\"card\\">\\n      <ul>\\n        <li><strong>Shape mistakes:</strong> one window is shape \\\\((T,)\\\\), but the model expects a batch shape \\\\((1,T)\\\\).</li>\\n        <li><strong>Random split:</strong> do not randomly mix future windows into training for forecasting evaluation.</li>\\n        <li><strong>Scaling leakage:</strong> fit scalers on training history only.</li>\\n        <li><strong>One-step vs multi-step confusion:</strong> one-step validation can be useful, but it is not a long-horizon forecast.</li>\\n        <li><strong>Error compounding:</strong> recursive forecasts drift if early predictions are wrong.</li>\\n        <li><strong>Unknown future features:</strong> do not feed true future weather, demand, sensor values, or target values unless they would be known at forecast time.</li>\\n      </ul>\\n    </div>\\n  </section>\\n\\n  <footer class=\\"card\\">\\n    <p class=\\"muted\\">\\n      Next natural step: replace the fixed linear window with recurrent hidden state. Chapter 10 shows how an RNN processes\\n      sequence inputs, then extends the same step-by-step idea to text translation and autoregressive decoding.\\n    </p>\\n  </footer>\\n</main>"}'),l={title:"Forecasting (Code): Coding an Autoregressive Linear Model in PyTorch",slug:"/part5-deep-learning-and-llms/09-autoregressive-linear-model",description:"Goal: implement an autoregressive (AR) linear model for time-series prediction, then evaluate it in the right way for a multi-step forecast.",sidebar_label:"9. Autoregressive linear model",pagination_label:"9. Autoregressive linear model",hide_title:!0,hide_table_of_contents:!0},d=void 0,c={},h=[];function p(e){return(0,i.jsx)(s.A,{content:o})}function g(e={}){const{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(p,{...e})}):p()}}}]);